/**
 * News API - 非遗资讯接口
 * 
 * 接口列表:
 * - getNews: 获取所有资讯 (支持筛选)
 * - getNewsDetail: 获取单条资讯详情
 * - getCategories: 获取资讯分类
 */

import request from './request.js'

export default {
  /**
   * 获取所有资讯
   * @param {object} params - 查询参数 { category, tag, search, page, limit }
   */
  getNews(params = {}) {
    return request.get('/news', { params })
  },

  /**
   * 获取单条资讯详情
   * @param {string} id - 资讯ID
   */
  getNewsDetail(id) {
    return request.get(`/news/${id}`)
  },

  /**
   * 获取资讯分类
   */
  getCategories() {
    return request.get('/news/categories')
  }
}
